(function(){ var root=document.currentScript?document.currentScript.parentElement:null; function mount(el){ el.innerHTML='<div style="padding:16px;font-family:sans-serif"><h3>Quick Notes Pro</h3><textarea id="qnp" style="width:100%;height:200px;border-radius:8px;padding:10px">'+(localStorage.getItem("qnp-note")||"")+'</textarea></div>'; el.querySelector("#qnp").addEventListener("input",function(e){ localStorage.setItem("qnp-note",e.target.value); }); } if(root)mount(root); window.__qnpMount=mount; })();